ACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAwM,CAAgB,8OAAG,EAAC,C;;;;;;;;;;;;ACA5N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ACAA,IAAMA,YAAY,GAAG,CAAC,QAAD,EAAW,QAAX,CAArB;AAEA,IAAMC,gBAAgB,GAAG;AACrB,QAAM,QADe;AAErB,QAAM,EAFe;AAGrB,QAAM;AAHe,CAAzB;AAMO,IAAMC,uBAAuB,GACpC;AACIC,OAAK,EAAE;AACHC,cAAU,EACV;AACIC,UAAI,EAAE,CAACC,MAAD,EAAS,IAAT,CADV;AAEIC,aAAO,EAAE,IAFb;AAGIC,eAAS,EAAE,mBAAAC,KAAK,EAChB;AACI,eAAO,CACH,EADG,SAEAT,YAFA,qBAGAU,MAAM,CAACC,IAAP,CAAYV,gBAAZ,CAHA,GAILW,OAJK,CAIGH,KAJH,MAIc,CAAC,CAJtB;AAKH;AAVL;AAFG,GADX;AAiBII,UAAQ,EAAE;AACNC,mBADM,6BAEN;AACI,UAAIb,gBAAgB,CAACc,cAAjB,CAAgC,KAAKX,UAArC,CAAJ,EACA;AACI,eAAOH,gBAAgB,CAAC,KAAKG,UAAN,CAAvB;AACH;;AAED,aAAO,KAAKA,UAAZ;AACH;AATK;AAjBd,CADO,C","file":"chunks/ceres-client-8.js","sourcesContent":["<template>\n    <div class=\"form-check\" :class=\"{ 'error': showError }\">\n        <input class=\"form-check-input\" type=\"checkbox\" :id=\"'privacy-policy-accept' + _uid\" :checked=\"value\" @change=\"onValueChanged($event.target.checked)\" data-testing=\"privacy-policy-accept-register\">\n        <label class=\"form-check-label\" :for=\"'privacy-policy-accept' + _uid\">\n            <span v-html=\"labelHtml\"></span><!--\n            --><sup>*</sup>\n        </label>\n    </div>\n</template>\n\n<script>\nexport default {\n\n    name: \"accept-privacy-policy-check\",\n\n    props: {\n        value: Boolean ,\n        showError: Boolean,\n        type: String\n    },\n\n    computed: {\n        labelHtml()\n        {\n            if (this.type){\n                const contactPrivacyPolicy = this.$translate(\"Ceres::Template.contactPrivacyPolicy\", {\"hyphen\": \"&shy;\"});\n                const html = `\n                    <!----><a href=\"${ App.urls.privacyPolicy }\" target=\"_blank\" class=\"text-appearance\">\n                        <span>${ contactPrivacyPolicy }</span>\n                    </a><!---->\n                `;\n\n            return this.$translate(\"Ceres::Template.contactAcceptPrivacyPolicy2\", {policy: html});\n\n            } else {\n\n                const contactPrivacyPolicy = this.$translate(\"Ceres::Template.contactPrivacyPolicy\", {\"hyphen\": \"&shy;\"});\n                const html = `\n                    <!----><a href=\"${ App.urls.privacyPolicy }\" target=\"_blank\" class=\"text-appearance\">\n                        <span>${ contactPrivacyPolicy }</span>\n                    </a><!---->\n                `;\n\n                return this.$translate(\"Ceres::Template.contactAcceptPrivacyPolicy\", {policy: html});\n\n            }\n        }\n    },\n\n    methods:\n    {\n        onValueChanged(value)\n        {\n            this.$emit(\"input\", value);\n        }\n    }\n}\n</script>","<template>\n    <div>\n        <form ref=\"form\" method=\"post\" class=\"mb-3 login-pwd-reset\">\n            <div class=\"input-unit\" data-validate=\"mail\">\n                <input type=\"email\" name=\"email\" autocomplete=\"email\" data-testing=\"guest-login-input\" :id=\"_uid\" v-model=\"email\" data-autofocus>\n                <label :for=\"_uid\">{{ $translate(\"Ceres::Template.loginEmail\") }}*</label>\n            </div>\n            <span class=\"error-msg\">{{ $translate(\"Ceres::Template.loginEnterConfirmEmail\") }}</span>\n            <div class=\"col-12 p-0\" v-if=\"enableConfirmingPrivacyPolicy\">\n                <accept-privacy-policy-check class=\"my-3 mb-0\" type=\"guest-login\" v-model=\"privacyPolicyAccepted\" @input=\"privacyPolicyValueChanged($event)\" :show-error=\"privacyPolicyShowError\"></accept-privacy-policy-check>\n            </div>\n            <div class=\"text-right\">\n                <button @click.prevent=\"validate\" :disabled=\"isDisabled\" class=\"btn btn-primary btn-medium btn-appearance\" :class=\"buttonSizeClass\" data-testing=\"guest-login-button\">\n                    {{ $translate(\"Ceres::Template.loginNext\") }}\n                    <icon icon=\"arrow-right\" :loading=\"isDisabled\"></icon>\n                </button>\n            </div>\n        </form>\n    </div>\n</template>\n\n<script>\nimport { ButtonSizePropertyMixin } from \"../../../mixins/buttonSizeProperty.mixin\";\n\nimport ApiService from \"../../../services/ApiService\";\nimport AutoFocusService from \"../../../services/AutoFocusService\";\nimport ValidationService from \"../../../services/ValidationService\";\nimport { navigateTo } from \"../../../services/UrlService\";\nimport { isDefined, isNullOrUndefined } from \"../../../helper/utils\";\nimport AcceptPrivacyPolicyCheck from \"../AcceptPrivacyPolicyCheck.vue\";\n\nexport default {\n    name: \"guest-login\",\n\n    mixins: [ButtonSizePropertyMixin],\n    components:\n    {\n        AcceptPrivacyPolicyCheck\n    },\n\n    props: {\n        backlink:\n        {\n            type: String\n        },\n        initialEmail:\n        {\n            type: String,\n            default: \"\"\n        }\n    },\n\n    data()\n    {\n        return {\n            email: \"\",\n            isDisabled: false,\n            privacyPolicyAccepted : false,\n            privacyPolicyShowError: false,\n            enableConfirmingPrivacyPolicy: App.config.global.registrationRequirePrivacyPolicyConfirmation,\n        };\n    },\n\n    created()\n    {\n        console.log(\"cre\"+this.checked)\n\n        if (!isNullOrUndefined(this.initialEmail) && this.initialEmail.length > 0)\n        {\n            this.email = this.initialEmail;\n        }\n    },\n\n    mounted()\n    {\n        console.log(\"moun\"+this.checked)\n\n        this.$nextTick(() =>\n        {\n            // for old login view only (input in modal)\n            if(!isNullOrUndefined(this.$parent.$refs.guestModal))\n            {\n                this.$parent.$refs.guestModal.addEventListener(\"hidden.bs.modal\", () =>\n                {\n                    this.email = \"\";\n                    ValidationService.unmarkAllFie